  AwakerStory_96422_Content = {
    Text = "그는 자신의 인생이 최고의 맛을 추구하기 위해 존재한다고 생각했다.\n 왕세자의 의무, 가까운 사람들과의 간극, 도덕의 규율…… 그는 모든 고통을 잊고 미각 예술의 극치를 찾았다. 왕세자에서 군주로, 인간에서 신으로, 한 순간도 멈추지 않았다. 그는 모든 요리 방법을 숙달하고, 각 시체의 가장 미세한 차이를 감지했다. 그는 소원을 이루었지만, 환희 이후 항상 무언가를 놓친 듯한 기분이 들었다.\n 셀리네의 시체를 먹고 그녀의 영혼을 본 그 순간, 그는 비로소 깨달았다. 그 시체들이 생전에 지닌 이야기, 그 영혼들이 아쉬워하는 소원들이야말로 그가 계속해서 추구하고, 계속해서 맛보고 싶었던 것이었다.\n 식사는 기억하기 위함이며, 매 한 자리에서의 연회는 망자와 생명체의 재회이다——두레사인은 이 말을 장례 도시의 왕좌에 새겼다. 그를 보호해 달라는 사람들에게, 그는 기억과 안식을 주기로 했다."
  },
